package com.aicharacter.v3;
import org.json.JSONObject;
public final class CaretakerLogEntry {public long time;public String event,detail,observationId="",transactionId="",result="";public CaretakerLogEntry(long t,String e,String d){time=t;event=e;detail=d;}public CaretakerLogEntry(long t,String e,String d,String o,String tx,String r){this(t,e,d);observationId=o;transactionId=tx;result=r;}public JSONObject toJson(){JSONObject j=new JSONObject();try{j.put("time",time);j.put("event",event);j.put("detail",detail);j.put("observationId",observationId);j.put("transactionId",transactionId);j.put("result",result);}catch(Exception ignored){}return j;}public static CaretakerLogEntry fromJson(JSONObject j){return new CaretakerLogEntry(j.optLong("time"),j.optString("event"),j.optString("detail"),j.optString("observationId"),j.optString("transactionId"),j.optString("result"));}}
